#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
ENV_FILE="${ROOT_DIR}/deploy/.env"

echo "Generating fresh cryptographic secrets for ATM Card Processor..."

PG_PASSWORD=$(openssl rand -base64 24)
JWT_SECRET=$(openssl rand -base64 48)
K1_KEY=$(openssl rand -base64 32)
HASH_KEY=$(openssl rand -base64 32)
ADMIN_PASSWORD=$(openssl rand -base64 16)

cat <<EOF > "${ENV_FILE}"
# Generated by scripts/gen-secrets.sh on $(date -u +"%Y-%m-%dT%H:%M:%SZ")

POSTGRES_DB=minicard
POSTGRES_USER=minicard
POSTGRES_PASSWORD=${PG_PASSWORD}
SPRING_DATASOURCE_URL=jdbc:postgresql://postgres:5432/minicard
SPRING_DATASOURCE_USERNAME=minicard
SPRING_DATASOURCE_PASSWORD=${PG_PASSWORD}

APP_SECURITY_JWT_SECRET=${JWT_SECRET}
APP_SECURITY_COOKIE_SECURE=false
APP_SECURITY_CORS_ALLOWED_ORIGINS=

APP_CRYPTO_PAN_CURRENT_KEY_ID=k1
APP_CRYPTO_PAN_KEYS_K1=${K1_KEY}
APP_CRYPTO_PAN_HASH_KEY=${HASH_KEY}

APP_BOOTSTRAP_ADMIN_EMAIL=admin@minicard.local
APP_BOOTSTRAP_ADMIN_PASSWORD=${ADMIN_PASSWORD}

APP_CARDS_BIN=990000
APP_CARDS_EXPOSE_PAN_ON_ISSUE=true
APP_BUSINESS_ZONE=Asia/Kathmandu
APP_FRAUD_FLAG_THRESHOLD=50
APP_FRAUD_DECLINE_THRESHOLD=80
APP_DISPUTES_EVIDENCE_DAYS=7
APP_DISPUTES_MAX_AGE_DAYS=120
APP_DISPUTES_DEADLINE_JOB_CRON=0 0 * * * *

SPRING_PROFILES_ACTIVE=prod,demo
DEMO_DATA=true
SPRINGDOC_ENABLED=false
EOF

chmod 600 "${ENV_FILE}"
echo "Wrote configuration and secrets to ${ENV_FILE}"
echo "Bootstrap admin email: admin@minicard.local"
echo "Bootstrap admin password: ${ADMIN_PASSWORD}"
